import { useCallback, useLayoutEffect, useState } from 'react';
import { reducerManager } from '01_app/storeManager';
export function useDynamicReducerLoader(reducers, removeAfterUnmount = true) {
    const [isMountedReducer, setIsMountedReducer] = useState(false);
    const mountReducerLoader = useCallback((reducersInner) => {
        if (Object.keys(reducersInner).length === 0) {
            setIsMountedReducer(true);
            return;
        }
        Object.entries(reducersInner).forEach(([key, reducer]) => {
            reducerManager.add(key, reducer);
        });
        setIsMountedReducer(true);
    }, []);
    const unmountReducerLoader = useCallback((reducersInner) => {
        if (Object.keys(reducersInner).length === 0)
            return;
        Object.entries(reducersInner).forEach(([key,]) => {
            reducerManager.remove(key);
            setIsMountedReducer(false);
        });
    }, []);
    // useLayoutEffect, а не useEffect: реєстрація й перерендер відбуваються до
    // відмальовки, тож заглушка RTKWrapper не блимає кадром, коли чанк уже
    // завантажений (раніше вона показувалась на кожному монтуванні).
    useLayoutEffect(() => {
        mountReducerLoader(reducers);
        return () => {
            if (removeAfterUnmount) {
                unmountReducerLoader(reducers);
            }
        };
        // eslint-disable-next-line
    }, []);
    return { isMountedReducer, mountReducerLoader, unmountReducerLoader };
}
