import { chartChrome, chartSeries, chartText } from '06_shared/constants/colors';
import { chartFont, SPACE } from '06_shared/constants/tokens';
export const prepareAnalysisChartDataAndOptions = (lag_price_list, lag_buy, lag_sell, theme) => {
    const { axis: accentColor, grid: noAccentColor, baseline } = chartChrome(theme);
    const labels = [];
    const null_list = [];
    const corr_buy_list = [];
    const corr_sell_list = [];
    lag_price_list.forEach(i => {
        labels.push(String(i.lag));
        null_list.push(0);
        corr_buy_list.push(i.corr_buy);
        corr_sell_list.push(i.corr_sell);
    });
    const data = {
        labels,
        datasets: [
            {
                label: undefined,
                data: null_list,
                borderColor: baseline,
                yAxisID: 'y1',
                pointRadius: 0,
                tension: 0.04,
                borderWidth: 1,
                postfix: '',
            },
            {
                label: 'Correlation Sell',
                data: corr_sell_list,
                ...chartSeries(theme, 'short'),
                yAxisID: 'y1',
                pointRadius: 0,
                tension: 0.04,
                fill: true,
                borderWidth: 1,
                postfix: '',
            },
            {
                label: 'Correlation Buy',
                data: corr_buy_list,
                ...chartSeries(theme, 'long'),
                yAxisID: 'y1',
                pointRadius: 0,
                tension: 0.04,
                fill: true,
                borderWidth: 1,
                postfix: '',
            },
        ],
    };
    const options = {
        responsive: true,
        maintainAspectRatio: false,
        interaction: {
            mode: 'index',
            intersect: false,
        },
        animation: {
            duration: 250,
            easing: 'easeInOutCubic',
        },
        stacked: false,
        plugins: {
            legend: {
                display: false,
            },
            tooltip: {
                enabled: true,
                titleFont: chartFont('body'),
                bodyFont: chartFont('bodyS'),
            },
            annotation: {
                annotations: {
                    nullY: {
                        type: 'line',
                        scaleID: 'x',
                        yScaleID: 'y1',
                        value: '0',
                        borderColor: baseline,
                        borderWidth: 1,
                    },
                    maxBuy: {
                        type: 'line',
                        yScaleID: 'y1',
                        xMin: `${lag_buy.lag_at_max_corr}`,
                        xMax: `${lag_buy.lag_at_max_corr}`,
                        yMin: 0,
                        yMax: lag_buy.max_corr,
                        borderColor: chartSeries(theme, 'long').borderColor,
                        borderWidth: 1,
                        label: {
                            display: true,
                            content: `Max Buy Correlation: ${lag_buy.max_corr.toFixed(3)} (${lag_buy.lag_at_max_corr})`,
                            position: 'end',
                            yAdjust: -20,
                            backgroundColor: chartSeries(theme, 'long').backgroundColor,
                            color: chartText(theme, 'long'),
                            font: chartFont('bodyS'),
                            padding: SPACE.xs,
                        },
                    },
                    maxSell: {
                        type: 'line',
                        yScaleID: 'y1',
                        xMin: `${lag_sell.lag_at_max_corr}`,
                        xMax: `${lag_sell.lag_at_max_corr}`,
                        yMin: 0,
                        yMax: lag_sell.max_corr,
                        borderColor: chartSeries(theme, 'short').borderColor,
                        borderWidth: 1,
                        label: {
                            display: true,
                            content: `Max Sell Correlation: ${lag_sell.max_corr.toFixed(3)} (${lag_sell.lag_at_max_corr})`,
                            position: 'end',
                            yAdjust: 20,
                            backgroundColor: chartSeries(theme, 'short').backgroundColor,
                            color: chartText(theme, 'short'),
                            font: chartFont('bodyS'),
                            padding: SPACE.xs,
                        },
                    },
                },
            },
        },
        scales: {
            x: {
                grid: {
                    display: true,
                    drawOnChartArea: false,
                    drawTicks: false,
                },
                ticks: {
                    color: accentColor,
                    maxTicksLimit: 48,
                    font: chartFont('bodyS'),
                },
                border: {
                    color: accentColor,
                },
            },
            y1: {
                type: 'linear',
                display: true,
                position: 'left',
                grid: {
                    drawOnChartArea: false,
                    color: noAccentColor,
                    tickColor: accentColor,
                },
                min: -1,
                max: 1,
                ticks: {
                    color: accentColor,
                    font: chartFont('bodyS'),
                },
                border: {
                    color: accentColor,
                },
            },
        },
    };
    return { data, options };
};
